"""Stage 4 and stage 5 acceptance workflow: fan-out, barrier, failure policy, resume.

Phase 1 runs three cheap agents at once, each in its own worktree, each owning
one file. The third is briefed to leave its work uncommitted, so it fails
`commits_past_base` and `tree_clean` on purpose and the quarantine policy takes
it out of the run.

Phase 2 runs one agent in the integration worktree. Its only job is to read its
own position block back, which is how the check proves that the quarantined step
is named to every later agent under the "Quarantined, excluded from
consolidation" heading.

Stage 5 reuses this workflow unchanged for the cached resume, then changes the
`integrator_note` argument, which is part of the last phase's brief and so part
of its fingerprint, for the partial resume.

    python -m ohflow.cli run --workflow <this file> --out <runs root> \\
        --args repo=<scratch repo> --args wt_root=<worktree root>
"""

from __future__ import annotations

from pathlib import Path

from ohflow.workflow import (CheckSpec, GateSpec, ModelConfig, Phase, Workflow, Step,
                             ToolPolicy, AgentSpec, WorktreeSpec)

GLM_FLASH = ModelConfig(model="zai/glm-5.3-flash",
                        base_url="https://api.z.ai/api/coding/paas/v4",
                        api_key_env="ZAI_CODING_CN_API_KEY")

GOOD_BRIEF = """# Task

Create one file, `{name}.txt`, in the root of this worktree. It holds exactly
one line: `{name} was here`.

Commit it. The commit message says what you did in one line. Author it clean:
no `Co-Authored-By` line naming a model, no generated-with footer.

# Acceptance, checked by the orchestrator and not by you

- `git log --oneline` shows at least one commit past the base.
- `git status --porcelain` prints nothing.
- `git diff --name-only <base>..HEAD` names `{name}.txt` and nothing else.

# Your report

End your final message with a line reading exactly `DONE`.
"""

FAILING_BRIEF = """# Task

Create one file, `{name}.txt`, in the root of this worktree. It holds exactly
one line: `{name} is unfinished`.

**Do not commit it and do not stage it.** Leave it in the working tree exactly
as you wrote it. This step is deliberately incomplete: another part of this run
is testing what happens to a step that does not finish its work, and your job is
to be that step.

Run no git command that changes the repository.

# Your report

End your final message with a line reading exactly `STOPPED`.
"""

INTEGRATOR_BRIEF = """# Task

Read the position block at the top of this brief. It is generated by the
orchestrator from the run log, so it states what actually happened in the
phase before you.

Write a short report naming, for each step of the previous phase:

- its coordinate,
- whether its gate passed,
- and, for any step listed under "Quarantined, excluded from consolidation",
  the branch that is excluded.

Change no file. Run no git command that changes the repository.
{note}

# Your report

End your final message with a line reading exactly `REPORTED`.
"""


def _agent(role: str, brief: str, skills_dir, skills, max_iter: int) -> AgentSpec:
    return AgentSpec(
        role=role,
        brief=brief,
        model=GLM_FLASH,
        harness_executor="pi",
        tools=ToolPolicy(preset="default", enable_browser=False,
                         enable_sub_agents=False),
        skills=tuple(skills),
        skills_dir=skills_dir,
        max_iterations=max_iter,
    )


def build(args: dict) -> Workflow:
    repo = Path(args["repo"])
    wt_root = Path(args.get("wt_root", str(repo.parent / "s4wt")))
    base = args.get("base", "main")
    prefix = args.get("prefix", "ohflow/s4")
    skills_dir = Path(args["skills_dir"]) if args.get("skills_dir") else None
    skills = [s for s in str(args.get("skills", "")).split(",") if s]
    max_iter = int(args.get("max_iterations", 40))
    timeout = int(args.get("execution_timeout_s", 900))
    note = str(args.get("integrator_note", ""))

    names = ("alpha", "beta", "gamma")
    worktrees = tuple(
        WorktreeSpec(name=n, path=wt_root / n, branch=f"{prefix}-{n}", base=base,
                     node_modules_mode="none")
        for n in names
    ) + (
        WorktreeSpec(name="integration", path=wt_root / "integration",
                     branch=f"{prefix}-integration", base=base,
                     node_modules_mode="none"),
    )

    def good_gate(name: str) -> GateSpec:
        return GateSpec(checks=(
            CheckSpec("commits_past_base", {"min": 1}),
            CheckSpec("tree_clean", {}),
            CheckSpec("ownership", {"allowed": [f"{name}.txt"]}),
            CheckSpec("no_ai_attribution", {}),
            CheckSpec("final_message_matches", {"regex": r"^DONE\s*$"}),
        ))

    # Stage 5's first check wants every step cached on a resume, and a
    # quarantined step is never a cache hit: section 4.4 caches only a record
    # whose status is `passed`. `gamma_brief=good` turns the deliberately
    # failing step into a passing one so that check has a workflow it can hold on.
    gamma_fails = str(args.get("gamma_brief", "failing")) != "good"

    steps = []
    for n in names:
        failing = n == "gamma" and gamma_fails
        template = FAILING_BRIEF if failing else GOOD_BRIEF
        steps.append(Step(
            id=n,
            kind="agent",
            worktree=n,
            write_scope=(f"{n}.txt",),
            execution_timeout_s=timeout,
            note=("briefed to leave its work uncommitted, so it fails its gate "
                  "on purpose") if failing else f"writes {n}.txt and commits it",
            agent=_agent("implementer", template.format(name=n), skills_dir,
                         skills, max_iter),
            gate=good_gate(n),
        ))

    batch = Phase(
        name="Batch",
        steps=tuple(steps),
        on_step_failure="quarantine",
        min_success="any",
        max_parallel=3,
    )

    integrate = Phase(
        name="Integrate",
        on_step_failure="continue",
        min_success="all",
        steps=(Step(
            id="integrator",
            kind="agent",
            worktree="integration",
            depends_on=names,
            execution_timeout_s=timeout,
            note="reads its own position block back",
            agent=_agent("integrator",
                         INTEGRATOR_BRIEF.format(note=note),
                         skills_dir, skills, max_iter),
            gate=GateSpec(checks=(
                CheckSpec("tree_clean", {}),
                CheckSpec("final_message_matches", {"regex": r"^REPORTED\s*$"}),
            )),
        ),),
    )

    return Workflow(
        name="stage4-fanout",
        repo=repo,
        base_branch=base,
        baseline_cmd=None,
        max_parallel=int(args.get("max_parallel", 3)),
        args=dict(args),
        worktrees=worktrees,
        phases=(batch, integrate),
    )
